function solution(n, k, d) {
  const memo = Array.from({ length: 2 }, () => Array(n + 1).fill(false));

  function solve(n, k, d, flag) {
    const idx = flag ? 1 : 0;
    if (memo[idx][n] !== false) return memo[idx][n];
    if (n === 0 && flag) return 1;
    if (n === 0 && !flag) return 0;
    let cnt = 0;
    for (let i = 1; i <= k; i++) {
      if (n - i >= 0) {
        cnt += solve(n - i, k, d, flag || (i >= d));
      }
    }
    memo[idx][n] = cnt;
    return cnt;
  }

  solve(n, k, d, false);
  return memo[0][n] % 1000000007;
}

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
console.log(solution(input[0], input[1], input[2]));

